from lib import *
L = lambda *a, **k: lesson(3, "A0", *a, **k)
L(1, "Моя сім'я", "Назвати членів сім'ї й представити їх.",
 "Щоб представити людину, кажуть This is…: This is my mother — «Це моя мама». Слово is пропускати не можна. My не змінюється: my mother, my father, my friend.",
 [W("family", "/ˈfæməli/", "noun", "сім'я", "This is my family.", "Це моя сім'я."),
  W("mother", "/ˈmʌðə/", "noun", "мама, мати", "This is my mother.", "Це моя мама."),
  W("father", "/ˈfɑːðə/", "noun", "тато, батько", "My father is from Ukraine.", "Мій тато з України."),
  W("brother", "/ˈbrʌðə/", "noun", "брат", "This is my brother.", "Це мій брат."),
  W("sister", "/ˈsɪstə/", "noun", "сестра", "My sister is here.", "Моя сестра тут."),
  W("friend", "/frend/", "noun", "друг, подруга", "This is my friend Anna.", "Це моя подруга Анна."),
  W("this", "/ðɪs/", "pronoun", "це, цей", "This is Tom.", "Це Том."),
  W("is", "/ɪz/", "verb", "є (з he, she, it, this)", "This is my family.", "Це моя сім'я.")],
 [li("Card or cash?", "Повторимо. Ви платите карткою. Що відповісти?", ["Card, please.", "Coffee, please.", "That's all."], "Card or cash? — карткою чи готівкою?"),
  mt([("mother", "мама"), ("father", "тато"), ("brother", "брат"), ("sister", "сестра")], "Усі чотири слова закінчуються на -er, а th у них звучить дзвінко."),
  mt([("family", "сім'я"), ("friend", "друг"), ("this", "це"), ("my", "мій, моя")], "My — і «мій», і «моя»: слово не змінюється."),
  liu("This is my brother.", "Прослухайте. Кого представляє людина?", ["Брата", "Тата", "Друга"], "Brother — брат. Father — тато."),
  fb("This ___ my mother.", ["is", "are", "am"], "Після this завжди is: This is…"),
  fb("This is ___ sister.", ["my", "I", "you"], "My sister — моя сестра. I означає «я»."),
  bs("Це моя сім'я.", ["This", "is", "my", "family"], ["are", "your"], "This is my family."),
  liu("My father is from Ukraine.", "Прослухайте. Що каже людина?", ["Мій тато з України", "Мій брат з України", "Мій тато живе в Україні"], "Father — тато, is from — «є з»."),
  tr("Це мій друг.", ["This is my friend"], "This is my friend. Friend — і друг, і подруга."),
  li("This is my sister, Anna.", "Вам представили людину. Що сказати?", ["Nice to meet you, Anna.", "I'm fine, thanks.", "Here you are."], "Після знайомства кажуть Nice to meet you.")])
L(2, "Він і вона", "Розповісти про іншу людину: хто це і як його або її звати.",
 "He — «він», she — «вона». З ними стоїть is, у розмові скорочено: he's, she's. His — «його», her — «її»: His name is Tom. Her name is Anna.",
 [W("he", "/hiː/", "pronoun", "він", "He's my brother.", "Він мій брат."),
  W("she", "/ʃiː/", "pronoun", "вона", "She's my sister.", "Вона моя сестра."),
  W("his", "/hɪz/", "determiner", "його", "His name is Tom.", "Його звати Том."),
  W("her", "/hɜː/", "determiner", "її", "Her name is Anna.", "Її звати Анна."),
  W("husband", "/ˈhʌzbənd/", "noun", "чоловік (у шлюбі)", "This is my husband.", "Це мій чоловік."),
  W("wife", "/waɪf/", "noun", "дружина", "She's my wife.", "Вона моя дружина."),
  W("son", "/sʌn/", "noun", "син", "He's my son.", "Він мій син."),
  W("daughter", "/ˈdɔːtə/", "noun", "донька", "This is my daughter.", "Це моя донька.")],
 [fb("This is my ___, Tom.", ["brother", "sister", "mother"], "Том — чоловіче ім'я, тому brother.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("he", "він"), ("she", "вона"), ("his", "його"), ("her", "її")], "He — his, she — her: пари для чоловіка й жінки."),
  mt([("husband", "чоловік"), ("wife", "дружина"), ("son", "син"), ("daughter", "донька")], "У daughter літери gh не вимовляються."),
  fb("This is Anna. ___ is my wife.", ["She", "He", "Her"], "Про жінку — she. Her означає «її»."),
  fb("This is my son. ___ name is Max.", ["His", "He", "Her"], "«Його ім'я» — his name."),
  liu("She's my daughter.", "Прослухайте. Хто це?", ["Її донька", "Її сестра", "Її син"], "She's — це she is. Daughter — донька."),
  bs("Її звати Анна.", ["Her", "name", "is", "Anna"], ["his", "she"], "Her name is Anna — дослівно «її ім'я є Анна»."),
  mc("Як сказати «Він мій чоловік»?", ["He's my husband.", "His my husband.", "She's my husband."], "He's = he is. His означає «його»."),
  tr("Він мій син.", ["He's my son", "He is my son"], "He's my son."),
  li("What's his name?", "Вас питають про вашого брата. Що відповісти?", ["His name is Tom.", "Her name is Tom.", "My name is Tom."], "Питають про нього — відповідь починається з His name is…")])
L(3, "У мене є", "Сказати, хто і що у вас є.",
 "I have… — «у мене є…»: I have a brother. We have… — «у нас є…». Про багатьох додають -s: two brothers, three cats. Виняток: child — children.",
 [W("we", "/wiː/", "pronoun", "ми", "We have a dog.", "У нас є собака."),
  W("child", "/tʃaɪld/", "noun", "дитина", "I have a child.", "У мене є дитина."),
  W("children", "/ˈtʃɪldrən/", "noun", "діти", "We have two children.", "У нас двоє дітей."),
  W("parents", "/ˈpeərənts/", "noun", "батьки", "My parents live in Ukraine.", "Мої батьки живуть в Україні."),
  W("boy", "/bɔɪ/", "noun", "хлопчик", "I have a boy.", "У мене хлопчик."),
  W("girl", "/ɡɜːl/", "noun", "дівчинка", "We have a girl.", "У нас дівчинка."),
  W("dog", "/dɒɡ/", "noun", "собака", "I have a dog.", "У мене є собака."),
  W("cat", "/kæt/", "noun", "кіт", "We have two cats.", "У нас два коти.")],
 [fb("___ name is Anna.", ["Her", "She", "He"], "«Її ім'я» — her name.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("child", "дитина"), ("children", "діти"), ("parents", "батьки"), ("we", "ми")], "Child — одна дитина, children — діти. Це слово треба запам'ятати."),
  mt([("boy", "хлопчик"), ("girl", "дівчинка"), ("dog", "собака"), ("cat", "кіт")], "Boy і girl — про дітей."),
  liu("We have two children.", "Прослухайте. Скільки дітей у сім'ї?", ["Двоє", "Троє", "Одна"], "Two children — двоє дітей."),
  fb("I ___ a sister.", ["have", "am", "is"], "«У мене є» — I have."),
  mc("Як сказати «три коти»?", ["three cats", "three cat", "cats three"], "Коли предметів більше одного, додають -s: cats."),
  fb("We have two ___.", ["children", "child", "childs"], "Форма множини — children, а не childs."),
  bs("У мене є брат і сестра.", ["I", "have", "a", "brother", "and", "a", "sister"], ["is"], "I have a brother and a sister."),
  tr("У нас є собака.", ["We have a dog"], "We have a dog."),
  li("Do you have children?", "Вас питають, чи є у вас діти. У вас є син. Що відповісти?", ["Yes, I have a son.", "Yes, I'm a son.", "No, thank you."], "Відповідь: Yes, I have… і хто саме.")])
L(4, "Скільки вам років?", "Спитати про вік і назвати свій.",
 "How old are you? — «Скільки вам років?». Відповідь: I'm thirty або I'm thirty years old. Англійською кажуть «я є тридцять», тому потрібне am, а не have. Про інших: He's five. She's twenty.",
 [W("how old", "/ˌhaʊ ˈəʊld/", "phrase", "скільки років", "How old are you?", "Скільки вам років?"),
  W("year", "/jɪə/", "noun", "рік", "I'm thirty years old.", "Мені тридцять років."),
  W("old", "/əʊld/", "adjective", "старий; (про вік) має стільки років", "He's ten years old.", "Йому десять років."),
  W("young", "/jʌŋ/", "adjective", "молодий", "She's young.", "Вона молода."),
  W("twenty", "/ˈtwenti/", "number", "двадцять", "I'm twenty.", "Мені двадцять."),
  W("thirty", "/ˈθɜːti/", "number", "тридцять", "She's thirty.", "Їй тридцять."),
  W("forty", "/ˈfɔːti/", "number", "сорок", "He's forty.", "Йому сорок."),
  W("fifty", "/ˈfɪfti/", "number", "п'ятдесят", "My father is fifty.", "Моєму татові п'ятдесят.")],
 [fb("We ___ two cats.", ["have", "are", "is"], "«У нас є» — we have.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("twenty", "20"), ("thirty", "30"), ("forty", "40"), ("fifty", "50")], "Десятки закінчуються на -ty.", "З'єднайте слово з числом"),
  liu("How old are you?", "Прослухайте. Що вас питають?", ["Скільки вам років?", "Як справи?", "Звідки ви?"], "How old are you? — про вік. How are you? — про справи."),
  liu("I'm forty years old.", "Прослухайте. Скільки років людині?", ["40", "14", "50"], "Forty — сорок."),
  fb("I ___ thirty.", ["am", "have", "is"], "Про вік англійською кажуть I am, а не I have."),
  fb("My son is ten ___ old.", ["years", "year", "old"], "Більше одного року — years."),
  mc("Як сказати «Їй двадцять»?", ["She's twenty.", "She has twenty.", "Her twenty."], "She's twenty = she is twenty."),
  bs("Скільки вам років?", ["How", "old", "are", "you"], ["is", "years"], "How old are you?"),
  tr("Мені тридцять років.", ["I'm thirty years old", "I am thirty years old", "I'm thirty", "I am thirty"], "I'm thirty years old. Можна коротко: I'm thirty."),
  li("How old is your daughter?", "Вашій доньці п'ять років. Що відповісти?", ["She's five.", "He's five.", "I'm five."], "Про доньку — she: She's five.")])
L(5, "Хто це?", "Спитати, хто це, сказати, ким людина працює, і заперечити.",
 "Who is this? — «Хто це?». Перед професією ставлять a: She's a doctor. Щоб сказати «не», додають not після is або am: He's not my brother. I'm not a teacher.",
 [W("who", "/huː/", "pronoun", "хто", "Who is this?", "Хто це?"),
  W("man", "/mæn/", "noun", "чоловік (людина)", "Who is this man?", "Хто цей чоловік?"),
  W("woman", "/ˈwʊmən/", "noun", "жінка", "This woman is my mother.", "Ця жінка — моя мама."),
  W("teacher", "/ˈtiːtʃə/", "noun", "учитель, учителька", "She's a teacher.", "Вона вчителька."),
  W("doctor", "/ˈdɒktə/", "noun", "лікар, лікарка", "My father is a doctor.", "Мій тато лікар."),
  W("student", "/ˈstjuːdnt/", "noun", "студент, студентка", "I'm a student.", "Я студент."),
  W("not", "/nɒt/", "adverb", "не", "He's not my brother.", "Він не мій брат.")],
 [li("How old are you?", "Повторимо. Вам сорок. Що відповісти?", ["I'm forty.", "I have forty.", "I'm fine."], "Про вік — I'm і число."),
  mt([("teacher", "учитель"), ("doctor", "лікар"), ("student", "студент"), ("who", "хто")], "Три професії й питальне слово who."),
  mt([("man", "чоловік"), ("woman", "жінка"), ("boy", "хлопчик"), ("girl", "дівчинка")], "Man і woman — про дорослих, boy і girl — про дітей."),
  liu("Who is this?", "Прослухайте. Що вас питають?", ["Хто це?", "Що це?", "Де це?"], "Who — хто. What — що, where — де."),
  fb("She's ___ doctor.", ["a", "my", "is"], "Перед професією потрібне a: a doctor, a teacher."),
  fb("He's ___ my brother. He's my friend.", ["not", "no", "a"], "«Не» всередині речення — not. No — це окрема відповідь «ні»."),
  liu("My mother is a teacher.", "Прослухайте. Ким працює мама?", ["Учителькою", "Лікаркою", "Вона студентка"], "A teacher — учителька."),
  bs("Я не студент.", ["I'm", "not", "a", "student"], ["no", "is"], "I'm not a student: not стоїть після I'm."),
  tr("Хто це?", ["Who is this", "Who's this"], "Who is this?"),
  li("Who is this woman?", "Це ваша сестра. Що відповісти?", ["She's my sister.", "He's my sister.", "I'm a sister."], "Про жінку — she: She's my sister.")])
L(6, "Повторення: розповідь про сім'ю", "Розповісти про свою сім'ю: хто є, як звати, скільки років, ким працюють.",
 "Нових слів немає. Складаємо розповідь про сім'ю з усього, що було в розділі: This is…, He's…, Her name is…, I have…, She's thirty, He's a doctor.",
 [],
 [bs("Це моя сім'я.", ["This", "is", "my", "family"], ["his", "are"], "This is my family."),
  fb("I ___ a husband and two children.", ["have", "am", "is"], "«У мене є» — I have."),
  tr("Мій чоловік — лікар.", ["My husband is a doctor"], "My husband is a doctor. Перед професією — a."),
  fb("He's forty years ___.", ["old", "young", "year"], "Вік: forty years old."),
  fb("This is my son. ___ name is Max.", ["His", "Her", "He"], "«Його ім'я» — his name."),
  liu("This is my daughter. Her name is Kate. She's ten.", "Прослухайте. Що ви дізналися?", ["Доньку звати Кейт, їй 10", "Сина звати Кейт, йому 10", "Доньку звати Кейт, їй 2"], "Daughter — донька, her name — її ім'я, she's ten — їй десять."),
  li("Who is this man?", "На фото ваш тато. Що відповісти?", ["He's my father.", "She's my father.", "He's my son."], "Про чоловіка — he: He's my father."),
  mc("Як сказати «У нас є собака й кіт»?", ["We have a dog and a cat.", "We are a dog and a cat.", "We have dog and cat a."], "We have… і a перед кожною твариною."),
  tr("Вона не моя сестра.", ["She's not my sister", "She is not my sister", "She isn't my sister"], "She's not my sister."),
  li("Do you have a brother or a sister?", "У вас є сестра. Що відповісти?", ["I have a sister.", "I'm a sister.", "Her name is sister."], "Вас питають, хто у вас є: I have a sister.")],
 review=True)
